WITH parsed AS (SELECT id, customer_id, items, ship_to, attributes, COALESCE(attributes['device'], 'direct') AS device_or_default, ship_to.zip AS ship_zip FROM carts) SELECT customer_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(DISTINCT device_or_default) AS distinct_device_or_defaults FROM parsed GROUP BY customer_id
